package ai.mlg.zero

/** The MLG engine (mlg/engine, C), through app/src/main/cpp/mlg_jni.c. Handles are 0 on failure. */
object Native {
    init {
        System.loadLibrary("mlg")
    }

    fun interface ByteSink {
        /** Each generated byte; return true to stop. */
        fun onByte(b: Int): Boolean
    }

    @JvmStatic external fun lastError(): String
    @JvmStatic external fun setThreads(n: Int)
    @JvmStatic external fun getThreads(): Int

    @JvmStatic external fun coreOpen(path: String): Long
    @JvmStatic external fun coreClose(h: Long)
    /** d_model, layers, heads, experts, top_k, ffn_mult, ctx, wtype, params */
    @JvmStatic external fun coreInfo(h: Long): LongArray
    /** ms per prompt byte, ms per generated byte */
    @JvmStatic external fun coreBench(h: Long): DoubleArray
    @JvmStatic external fun coreBitsPerByte(h: Long, text: ByteArray): Double
    @JvmStatic external fun coreGenerate(h: Long, prompt: ByteArray, maxOut: Int, temperature: Float, topP: Float,
                                         seed: Long, sink: ByteSink?): ByteArray

    @JvmStatic external fun knowOpen(path: String): Long
    @JvmStatic external fun knowClose(h: Long)
    @JvmStatic external fun knowCount(h: Long): Int
    /** [id0, score0, id1, score1, ...] */
    @JvmStatic external fun knowSearch(h: Long, query: ByteArray, top: Int): FloatArray
    @JvmStatic external fun knowText(h: Long, id: Int): ByteArray
    @JvmStatic external fun knowTitle(h: Long, id: Int): ByteArray

    @JvmStatic external fun routerOpen(path: String): Long
    @JvmStatic external fun routerClose(h: Long)
    @JvmStatic external fun routerNames(h: Long): Array<String>
    @JvmStatic external fun routerRoute(h: Long, text: ByteArray): FloatArray
}
